.@"justify-content" => |*val| {
self.box_pack = null;
            self.flex_pack = null;
            _ = self.handlePropertyHelper(dest, context, "justify_content", (&val.*[0]), val.*[1]);
},
.@"box-pack" => |*val| {
_ = self.handlePropertyHelper(dest, context, "box_pack", (&val.*[0]), val.*[1]);
},
.@"flex-pack" => |*val| {
_ = self.handlePropertyHelper(dest, context, "flex_pack", (&val.*[0]), val.*[1]);
