            _ = self.handlePropertyMaybeFlush(dest, context, "justify_content", (&val.justify), VendorPrefix.NONE);
            _ = self.handlePropertyHelper(dest, context, "align_content", (&val.@"align"), VendorPrefix.NONE);
            _ = self.handlePropertyHelper(dest, context, "justify_content", (&val.justify), VendorPrefix.NONE);
