pub fn flush(self: *AlignHandler, dest: *css.DeclarationList, context: *css.PropertyHandlerContext) void {
            if ((!self.has_any)) {
                return;
            }
            self.has_any = false;
            var align_content = bun.take((&self.align_content));
            _ = &align_content;
            var justify_content = bun.take((&self.justify_content));
            _ = &justify_content;
            var align_self = bun.take((&self.align_self));
            _ = &align_self;
            var justify_self = bun.take((&self.justify_self));
            _ = &justify_self;
            var align_items = bun.take((&self.align_items));
            _ = &align_items;
            var justify_items = bun.take((&self.justify_items));
            _ = &justify_items;
            const row_gap = bun.take((&self.row_gap));
            const column_gap = bun.take((&self.column_gap));
            var box_align = bun.take((&self.box_align));
            _ = &box_align;
            var box_pack = bun.take((&self.box_pack));
            _ = &box_pack;
            var flex_line_pack = bun.take((&self.flex_line_pack));
            _ = &flex_line_pack;
            var flex_pack = bun.take((&self.flex_pack));
            _ = &flex_pack;
            var flex_align = bun.take((&self.flex_align));
